package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.widget.*;import android.media.*;import android.webkit.WebView;import java.util.*;
/** Uses Android settings; no manufacturer-specific packages or automatic telemetry. */
public final class DeviceCompatibility {
 public static void open(Context c,Intent intent){try{c.startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){try{c.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+c.getPackageName())));}catch(Exception ignored){Toast.makeText(c,"Abre Ajustes del teléfono > Aplicaciones > Despierta",Toast.LENGTH_LONG).show();}}}
 public static void problem(Context c,Exception e){if(c instanceof Activity)Toast.makeText(c,"No se pudo iniciar la vigilancia. Revisa permisos en Listo para viajar.",Toast.LENGTH_LONG).show();c.getSharedPreferences("schedule",0).edit().putString("error",e.getClass().getSimpleName()).apply();TripHistory.add(c,"No se pudo programar o iniciar la vigilancia: "+e.getClass().getSimpleName());}
 public static String diagnostics(Context c){String version="desconocida";try{version=c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;}catch(Exception ignored){}Vibrator v=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);String web="no disponible";try{android.content.pm.PackageInfo p=WebView.getCurrentWebViewPackage();if(p!=null)web=p.versionName;}catch(Exception ignored){}return "Despierta "+version+"\nEquipo: "+Build.MANUFACTURER+" "+Build.MODEL+"\nAndroid "+Build.VERSION.RELEASE+" / API "+Build.VERSION.SDK_INT+"\nWebView: "+web+"\nVibrador: "+(v!=null&&v.hasVibrator())+"\nPermisos de programación: "+ScheduleController.permitted(c)+"\nNotificaciones habilitadas: "+c.getSystemService(NotificationManager.class).areNotificationsEnabled()+"\nSolo audífonos: "+AudioSafety.strict(c)+"\nAuriculares detectados: "+(AudioSafety.headset(c)!=null)+"\nÚltimo error de programación: "+c.getSharedPreferences("schedule",0).getString("error","ninguno")+"\nSin coordenadas, nombres de alarmas ni identificadores del dispositivo.";}
 public static void attach(Activity c,LinearLayout page){JourneyOptions.add(c,page,"Compatibilidad y diagnóstico  ›",()->show(c));}
 static void show(Activity c){
  String info=diagnostics(c);Dialog dialog=new Dialog(c);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);
  LinearLayout panel=new LinearLayout(c);panel.setOrientation(1);int pad=JourneyOptions.dp(c,20);panel.setPadding(pad,pad,pad,pad);
  android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(VibrationEditor.color(c,"surface",0xff17392e));bg.setCornerRadius(JourneyOptions.dp(c,26));panel.setBackground(bg);
  panel.addView(JourneyOptions.text(c,"Compatibilidad",23));panel.addView(JourneyOptions.text(c,"Android 8.0 o posterior. La vigilancia con pantalla bloqueada depende de los permisos y las restricciones de batería del teléfono.",15));panel.addView(JourneyOptions.text(c,info,15));
  JourneyOptions.add(c,panel,"Copiar diagnóstico",()->{((ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Diagnóstico Despierta",info));Toast.makeText(c,"Diagnóstico copiado. Compártelo si quieres reportar un problema.",Toast.LENGTH_LONG).show();});JourneyOptions.add(c,panel,"Cerrar",()->dialog.dismiss());
  ScrollView scroll=new ScrollView(c);scroll.addView(panel);dialog.setContentView(scroll);dialog.show();android.view.Window window=dialog.getWindow();window.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));window.setGravity(android.view.Gravity.BOTTOM);panel.measure(android.view.View.MeasureSpec.makeMeasureSpec(c.getResources().getDisplayMetrics().widthPixels,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(0,android.view.View.MeasureSpec.UNSPECIFIED));window.setLayout(-1,Math.min(panel.getMeasuredHeight(),(int)(c.getResources().getDisplayMetrics().heightPixels*.85)));
 }
}
